        for (let t = 0; t <= len; t += 0.8){ const a = at(s0 + t, off - w/2 - 0.4), b = at(s0 + t, off + w/2 + 0.4); boxP(wd, 0.12, 0.3, Math.hypot(b.x - a.x, b.z - a.z), (a.x + b.x)/2, yD + 4.55, (a.z + b.z)/2, -Math.atan2(a.q.uz, a.q.ux)); }
