    const yG = gMean(G, resP(P0, 60)), y0 = gMin(G, P0) - yG - 1.5, FH = 3.7, NL = 10;
    const LIME = {c:'#dccfb4', lc:'#ffe2b8', lk:0.7}, BRZ = {c:'#8b6a45', lc:'#ffc880', lk:0.9}, GLS = {c:'#45484a', m:1, lc:'#ffd7a0', lk:0.5, fh:3.7, cw:2.2};
    const GW = '#4d7738', LAWN = '#6e9a4b';
