          const a = Q[j], b = Q[(j+2) % Q.length]; const [nx, nz] = outN(Q, j); wallP(hp, [a[0] - nx*0.7, a[1] - nz*0.7], [b[0] - nx*0.7, b[1] - nz*0.7], 0.9, yt + 0.1, yt + 0.85);
