    const CR = {c:'#b9d3e6', m:0, lk:1.3, glow:'#9ec8ff', gk:0.5}, RIM = '#d0d6da', ROOFC = {c:'#9b958a', m:0, lk:0.2}, WGL = {c:'#384148', glow:'#ffe6c2', gk:0.6};
