    { const top = PT[PT.length - 1].r, c = cenP(top); let r = 0; for (const q of top) r = Math.max(r, Math.hypot(q[0] - c[0], q[1] - c[1]));
      LDome(g, r - 0.4, c[0], 251.5, c[1], {c:'#d6eaf6', m:1, lk:1.8}, 0.33, 28); LCyl(g, 0.25, 0.4, 1.2, c[0], 254.1, c[1], RIM, 8);
      LSph(g, 0.4, c[0], 255.3, c[1], {c:'#c22', glow:'#ff3020', gk:2}, 1, 6); }
