    const GRA = {c:'#cdb88a', m:0, lc:'#ffe0b0', lk:0.55}, GRA2 = '#b59d68', AT = {c:'#8fb4bc', glow:'#ffd9a8', gk:0.45, op:0.62};
    const yP = 27.5, yU = 90, yA = 78, yGm = gMean(G, resP(M, 60)), y0m = gMin(G, M) - yGm - 1.5;
    facetP(B.p(GRA), M, y0m, yP, 6, 0.9); flatP(B.p(ROOFC), M, yP);
