    prismP(B.p(MB2), offP(R, -0.2), yT, yT + 0.6, false);
    { const o = B.p(MB); for (let i = 0; i < R.length; i++){ const a = R[i], b = R[(i+1) % R.length], L = Math.hypot(b[0]-a[0], b[1]-a[1]), n = Math.floor(L/1.4);
        for (let j = 0; j < n; j++){ const t = (j + 0.5)/n; boxP(o, 0.55, 0.7, 0.4, a[0] + (b[0]-a[0])*t, yT + 0.6, a[1] + (b[1]-a[1])*t, -Math.atan2(b[1]-a[1], b[0]-a[0])); } } }
