    const BR = {c:'#a3523b', lc:'#ffc88a', lk:0.9}, GR = '#d3ccbc', ROOF = '#5b524c', GLS = {c:'#3a3640', glow:'#ffb768', gk:0.55};
    const box = (o, w, h, d, u, y, v) => F.box(o, w, h, d, u, y, v);
    // plinth / terrace
    prismP(B.p(GR), offP(R, -0.8), y0 - 1.5, 0.4, false);
    // nave u -18.4..-1.3, v -7.6..7.4 ; transept u -1.3..5.5, v -9.1..9.4 ; chancel u 5.5..10.1, v -6.8..6.7
    const NV = {u0:-18.4, u1:-1.3, v0:-7.6, v1:7.4, h:8.8, r:17.5}, TR = {u0:-1.3, u1:5.5, v0:-9.1, v1:9.4, h:8.8, r:17.0}, CH = {u0:5.5, u1:10.1, v0:-6.8, v1:6.7, h:7.6, r:14.2};
    for (const q of [NV, TR, CH]) box(B.p(BR), q.u1 - q.u0, q.h - 0.4, q.v1 - q.v0, (q.u0 + q.u1)/2, 0.4, (q.v0 + q.v1)/2);
    // granite plinth course, string course, eaves
    for (const q of [NV, TR, CH]){ box(B.p(GR), q.u1 - q.u0 + 0.3, 0.9, q.v1 - q.v0 + 0.3, (q.u0 + q.u1)/2, 0.4, (q.v0 + q.v1)/2); box(B.p(GR), q.u1 - q.u0 + 0.2, 0.3, q.v1 - q.v0 + 0.2, (q.u0 + q.u1)/2, 3.4, (q.v0 + q.v1)/2); box(B.p(GR), q.u1 - q.u0 + 0.25, 0.35, q.v1 - q.v0 + 0.25, (q.u0 + q.u1)/2, q.h - 0.35, (q.v0 + q.v1)/2); }
