    { const uc = (TR.u0 + TR.u1)/2, vc = (TR.v0 + TR.v1)/2, Ft = frame(F.p(uc, vc), -0.0817 + HP); gableF(Ft, B.p(ROOF), B.p(BR), -(TR.v1 - TR.v0)/2, (TR.v1 - TR.v0)/2, (TR.u1 - TR.u0)/2, TR.h, TR.r, 0.5); }
    { const vc = (CH.v0 + CH.v1)/2, Fc = frame(F.p(0, vc), -0.0817); gableF(Fc, B.p(ROOF), B.p(BR), CH.u0 - 0.4, CH.u1, (CH.v1 - CH.v0)/2, CH.h, CH.r, 0.4); }
    // ridge crosses / finials
