      for (let u = NV.u0 + 2.2; u < NV.u1 - 0.8; u += 3.4){
        for (const [v, s] of [[NV.v0, -1], [NV.v1, 1]]){ if (s > 0 && u < -12.6) continue; const nn = (() => { const a = F.p(0, 0), b = F.p(0, s); return [b[0] - a[0], b[1] - a[1]]; })();
          box(ob, 0.7, 5.6, 0.9, u - 1.7, 0.4, v + s*0.4); box(B.p(GR), 0.75, 0.3, 1.0, u - 1.7, 6.0, v + s*0.45);
          for (const du of [-0.55, 0.55]){ const q = F.p(u + du, v); archWin(o, q[0], q[1], nn, 0.75, 4.2, 6.8, 1.0, 0.06); } } }
      // west window (large lancet) and east window
