      { const a = F.p(0, 0), b = F.p(1, 0), ne = [b[0] - a[0], b[1] - a[1]]; const q = F.p(CH.u1, 0); archWin(o, q[0], q[1], ne, 2.6, 3.0, 6.6, 2.6, 0.06); }
      // transept end windows
