      for (const yy of [8.8, 14.6]) box(B.p(GR), w + 0.25, 0.35, w + 0.25, u, yy, v);
      for (const su of [-1, 1]) for (const sv of [-1, 1]) box(B.p(BR), 0.9, H - 1.6, 0.9, u + su*(w/2 + 0.15), 0.4, v + sv*(w/2 + 0.15));
