    // exposed diagonal bracing frames on the long faces (concrete): X frames in bays of 15 m between columns
    for (const s of [-1, 1]){ const v = s*(LV + 0.6);
      for (let u = -LU; u <= LU + 0.1; u += 15){ F.box(B.p(CON), 1.1, H + 0.5, 1.1, u, 0, v); }
      F.box(B.p(CON), 2*LU + 1, 1.0, 1.1, 0, H - 0.5, v); F.box(B.p(CON), 2*LU + 1, 0.8, 1.1, 0, 12.0, v);
      for (let u = -LU; u < LU - 1; u += 15) for (const [ya, yb] of [[0.5, 12.0], [12.8, H - 0.5]]){
        const a = F.p(u, v), b = F.p(u + 15, v); segP(B.p(CON), [a[0], ya, a[1]], [b[0], yb, b[1]], 0.45, 4); segP(B.p(CON), [b[0], ya, b[1]], [a[0], yb, a[1]], 0.45, 4); } }
